// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, uint256 v) public {
        address[] memory emptyTos = new address[](0);
        // The reference contract reverts when _tos is empty; the mutant returns true.
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, emptyTos, v));
        assertTrue(!success);
    }
}

